<script>
async function exportSVG() {
  const btn = document.getElementById('export-btn');
  btn.textContent = 'Generating...';
  btn.disabled = true;

  try {
    // Use html2canvas-like approach: serialize the poster to SVG via foreignObject
    const poster = document.getElementById('poster');
    const { width, height } = poster.getBoundingClientRect();

    // Clone poster for serialization
    const clone = poster.cloneNode(true);
    clone.style.position = 'absolute';
    clone.style.top = '-9999px';
    document.body.appendChild(clone);

    const serializer = new XMLSerializer();

    // Build SVG with foreignObject
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('xmlns', svgNS);
    svg.setAttribute('width', Math.round(width));
    svg.setAttribute('height', Math.round(height));
    svg.setAttribute('viewBox', `0 0 ${Math.round(width)} ${Math.round(height)}`);

    const fo = document.createElementNS(svgNS, 'foreignObject');
    fo.setAttribute('width', '100%');
    fo.setAttribute('height', '100%');

    const htmlNS = 'http://www.w3.org/1999/xhtml';
    const div = document.createElementNS(htmlNS, 'div');
    div.innerHTML = clone.outerHTML;

    fo.appendChild(div);
    svg.appendChild(fo);
    document.body.removeChild(clone);

    const svgStr = serializer.serializeToString(svg);
    const blob = new Blob([svgStr], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = 'state-of-dev-2024.svg';
    a.click();
    URL.revokeObjectURL(url);

    btn.textContent = 'Exported!';
    setTimeout(() => { btn.textContent = 'Export SVG'; btn.disabled = false; }, 2000);
  } catch (e) {
    console.error(e);
    btn.textContent = 'Export SVG';
    btn.disabled = false;
    alert('SVG export failed: ' + e.message);
  }
}
</script>

